window.FILM_WORK_PROMPTS={"work_id":"src-534eb63114e29d03","records":[{"work_id":"src-534eb63114e29d03","frame_id":"FG-2a4413044a9372a6","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/shallowgrave007.jpg","source_page":"https://film-grab.com/2017/01/03/shallow-grave/","scene":"昏暗室内，左侧一人坐于铺红床单的床沿，右侧一人赤足站立于蓝墙前，地面铺有花纹地毯，左侧床头柜上有一盏台灯。","analysis":"画面采用横向构图，人物分立左右两侧，中间留出大片蓝色墙面空间。左侧人物呈坐姿，全身可见，身着深色衣物；右侧人物呈站立姿态，全身可见，身着白色上衣与灰色长裙。光线从上方投射，在墙面形成明显的明暗分界，整体色调偏冷，红色床品与蓝色背景形成对比。","prompt":"昏暗的室内场景，左侧有一张铺着鲜红色床单的木床，一名身穿深色西装的人物坐在床沿，身体微向前倾。右侧一名身穿宽松白色衬衫和灰色长裙的人物赤足站立，面向左侧。背景是大面积的深蓝色墙壁，上方有一束光投射在墙面上形成亮区。地面铺着带有复杂花纹的深色地毯。左侧床头柜上放置着一盏台灯。整体画面色调阴郁，光影对比强烈，呈现出一种静谧而紧张的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T11:01:47-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/shallowgrave007.jpg","observed_dimensions":[500,276],"source_thumbnail_dimensions":[500,276],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-93b6eda5ccb7e98f","origin":"visual"},{"work_id":"src-534eb63114e29d03","frame_id":"FG-d0f63a75e3872baf","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/shallowgrave020.jpg","source_page":"https://film-grab.com/2017/01/03/shallow-grave/","scene":"黑暗环境中，两个明亮的方形车灯对称亮起，下方隐约可见车牌，周围弥漫着烟雾。","analysis":"画面采用对称构图，两个方形车灯位于左右两侧，亮度极高，形成强烈的视觉焦点。车灯下方中央位置有一块矩形车牌，文字依稀可辨。背景几乎全黑，车灯周围有烟雾或尘埃被光线照亮，形成朦胧的光晕效果。整体明暗对比强烈，光源为冷白色，营造出一种神秘且紧张的氛围。","prompt":"这是一张低分辨率的夜间画面，背景几乎完全黑暗。画面左右两侧各有一个明亮的方形车灯，发出强烈的冷白色光芒，光线在周围的烟雾或尘埃中形成明显的光束和光晕。两个车灯之间是模糊的深色格栅轮廓。在车灯下方中央位置，悬挂着一块矩形车牌，上面的字符“B422 AGG”在微弱的光线下依稀可见。整体画面呈现出高对比度的视觉效果，除了车灯和车牌区域外，其余部分都沉浸在深沉的黑暗中，营造出一种神秘且压抑的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T11:01:53-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/shallowgrave020.jpg","observed_dimensions":[500,276],"source_thumbnail_dimensions":[500,276],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-881b9e23f8de40b5","origin":"visual"},{"work_id":"src-534eb63114e29d03","frame_id":"FG-b4c7002c2ef46da5","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/shallowgrave033.jpg","source_page":"https://film-grab.com/2017/01/03/shallow-grave/","scene":"淡绿色墙面的室内大厅，一名人物站在中央，左侧立着高梯与自行车，右侧是带拱形窗的深色大门，右上方悬挂绿色灯笼。","analysis":"画面采用平视视角，环境占据绝大部分空间。人物位于画面中轴线偏左，全身可见，身形在高大空间中显得较小。左侧高梯斜靠天花板，右侧大门上方有半圆形采光窗。室内光线偏暗，主要光源来自右侧门窗，形成明暗对比，整体色调为冷绿与深灰。","prompt":"低分辨率室内静帧，淡绿色墙壁的大厅，一名身穿深色格纹外套的人物站在画面中央，全身可见。左侧有一架长木梯斜靠天花板，梯下停着一辆自行车，旁边是深色木门和木质柜子。右侧是一扇巨大的深色双开大门，上方有半圆形采光窗，右上方悬挂着两个绿色灯笼。室内光线昏暗，主要光源来自右侧门窗，在墙面和地面投下阴影，整体色调偏冷，呈现出一种静谧、空旷的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T11:02:03-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/shallowgrave033.jpg","observed_dimensions":[500,276],"source_thumbnail_dimensions":[500,276],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-57b008e3177a337d","origin":"visual"},{"work_id":"src-534eb63114e29d03","frame_id":"FG-c15d6a4e372882bf","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/shallowgrave046.jpg","source_page":"https://film-grab.com/2017/01/03/shallow-grave/","scene":"一名戴眼镜的男子位于画面左侧，身穿深蓝色上衣，身体前倾。他右手向前伸出，紧握一把巨大的青绿色手持工具，工具尖端指向画面右上方。背景为模糊的深青色墙面。","analysis":"画面采用浅景深构图，焦点清晰地落在前景的手部与青绿色工具上，人物面部及背景处于虚化状态。人物仅上半身可见，占据画面左半部分，工具占据右侧前景，形成强烈的视觉引导。光线柔和偏冷，整体色调以青绿和深蓝为主，明暗对比集中在手部与工具表面。","prompt":"低分辨率画面，色调偏冷。画面左侧是一名戴眼镜、棕色短发的男子，身穿深蓝色长袖上衣，身体略微前倾。他的右手向前伸出，紧握一把巨大的青绿色手持工具，工具头部呈圆柱状，前端有金属尖头，指向画面右上方。背景是模糊的深青色墙面，光线昏暗，焦点集中在前景的手部和工具上，人物面部虚化。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T11:02:09-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/shallowgrave046.jpg","observed_dimensions":[500,276],"source_thumbnail_dimensions":[500,276],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-5fb69d16e7e072a7","origin":"visual"},{"work_id":"src-534eb63114e29d03","frame_id":"FG-ba7c4e522df053c7","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/shallowgrave059.jpg","source_page":"https://film-grab.com/2017/01/03/shallow-grave/","scene":"一名金发人物面部侧卧于浅色平面上，头部占据画面左侧，右侧为深色衣物，画面底部边缘可见暗红色条状物质。","analysis":"构图极度紧凑，仅可见人物面部及右侧肩颈处的深灰色衣物，环境背景几乎不可见。视角为近距离俯视，光线从上方投射，在面部形成明暗对比，皮肤呈现冷色调，画面底部暗红色块与浅色底面形成色彩反差。","prompt":"低分辨率画面，一名金发人物面部侧卧，头部占据画面左侧大部分区域，面部皮肤在冷色调光线下呈现苍白质感，右侧可见深灰色衣物覆盖肩颈。人物面部朝向右下方，画面底部边缘为浅色平面，其上分布着暗红色条状物质。整体空间布局紧凑，背景被人物头部与衣物填满，光线集中在面部中央，四周逐渐变暗，色彩以冷灰、肤色与底部暗红为主。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T11:02:14-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/shallowgrave059.jpg","observed_dimensions":[500,276],"source_thumbnail_dimensions":[500,276],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-50f79ff66257aa44","origin":"visual"},{"work_id":"src-534eb63114e29d03","frame_id":"FG-cbb61b69db5526e4","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/shallowgrave008.jpg","source_page":"https://film-grab.com/2017/01/03/shallow-grave/","scene":"前景为模糊的红色物体，背景是黄色墙壁的室内，两人坐在棕色皮沙发上，旁边有绿色书柜和白色壁炉。","analysis":"构图采用前景虚化，红色物体占据左下角，形成视觉引导。中景两人背对镜头坐在沙发上，仅可见上半身轮廓。室内光线柔和，黄色墙面与蓝色窗帘形成冷暖对比，壁炉上方挂有两幅相框，整体色调温暖。","prompt":"低分辨率室内场景，前景左下角有一个巨大的模糊红色物体，占据画面约三分之一。背景是黄色墙壁的房间，左侧有蓝色窗帘。房间中央有一张棕色皮沙发，两人背对镜头坐在上面，左侧人物穿深色上衣，右侧人物穿浅色上衣。沙发后方是白色壁炉，上方挂着两幅相框。左侧墙边有一个绿色书柜，里面摆放着书籍。室内光线柔和，整体色调偏暖，呈现出一种安静的居家氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T16:32:43+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/shallowgrave008.jpg","observed_dimensions":[500,276],"source_thumbnail_dimensions":[500,276],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-5b1a5a464cbbfed9","origin":"visual"},{"work_id":"src-534eb63114e29d03","frame_id":"FG-f3dc3fa00bf09500","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/shallowgrave021.jpg","source_page":"https://film-grab.com/2017/01/03/shallow-grave/","scene":"黑暗环境中，一男一女并排坐着。左侧男子戴眼镜，右侧女子围着浅色围巾。两人均面向前方，背景漆黑，仅有人物面部和上半身被微弱光线照亮。","analysis":"构图紧凑，人物占据画面主要部分，背景几乎全黑。左侧男子位于画面左半部，右侧女子位于右半部，两人头部高度相近。光线从前方偏上位置投射，照亮面部和肩部，形成强烈的明暗对比。男子面部和眼镜反光明显，女子面部受光较柔和，围巾呈现暖黄色调。整体色调偏暗，以黑色和暗红色为主，局部有暖色光斑。","prompt":"黑暗背景中，一男一女并排坐着，仅上半身可见。左侧男子戴圆框眼镜，短发，身穿暗红色上衣，面部被前方光线照亮，眼镜片有反光。右侧女子红发，围着浅黄色花纹围巾，身穿深色衣物，面部受光柔和。两人均面向前方，表情平静。背景完全黑暗，无法辨识环境细节。光线从前方偏上位置投射，形成强烈的明暗对比，人物面部和肩部较亮，其余部分融入黑暗。整体色调偏暗，以黑色、暗红色和暖黄色为主。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T16:32:50+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/shallowgrave021.jpg","observed_dimensions":[500,276],"source_thumbnail_dimensions":[500,276],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-39233c0f96a45659","origin":"visual"},{"work_id":"src-534eb63114e29d03","frame_id":"FG-e4b235ce2067c9ad","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/shallowgrave034.jpg","source_page":"https://film-grab.com/2017/01/03/shallow-grave/","scene":"一条狭长明亮的室内走廊，两侧是大面积玻璃窗，尽头处有一个人影站立，地面光滑反光，整体环境空旷且对称。","analysis":"画面采用严格的中心对称构图，两侧窗框与天花板线条汇聚于中心，形成强烈的纵深感。人物位于画面远端中心，仅呈现为极小的深色轮廓，无法分辨具体姿态或细节。环境占据绝大部分画面，光线均匀明亮，色调以冷白和淡绿为主，地面反射出窗户的亮区。","prompt":"低分辨率的室内走廊画面，采用中心对称构图，视线向远处延伸。两侧是连续的玻璃窗，窗框呈淡绿色，窗外可见模糊的绿色植被。天花板为白色方格吊顶，地面是光滑的浅色材质，清晰地反射出两侧窗户的亮光。在走廊尽头的中心位置，有一个极小的人物剪影站立，身穿深色衣物，因距离过远无法辨认细节。整体光线明亮均匀，色调偏冷，呈现出一种空旷、静谧且略带疏离的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T16:32:55+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/shallowgrave034.jpg","observed_dimensions":[500,276],"source_thumbnail_dimensions":[500,276],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-658ccc3f9e6be962","origin":"visual"},{"work_id":"src-534eb63114e29d03","frame_id":"FG-337e75b3f62bb36d","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/shallowgrave047.jpg","source_page":"https://film-grab.com/2017/01/03/shallow-grave/","scene":"昏暗环境中，一名戴眼镜的年轻男子低头向下看，画面仅显示其头部与肩颈部位，背景完全隐没于黑暗之中。","analysis":"构图极度紧凑，人物面部占据画面右侧约三分之二区域，左侧可见部分肩颈及浅色衣物边缘。视角略微俯视，光线从上方投射，照亮额头、鼻梁及眼镜片，形成强烈明暗对比。整体色调偏暖，以深褐与黑色为主，眼镜片反射出微弱光点，其余部分细节被阴影吞没。","prompt":"昏暗低光环境，一名年轻男子低头向下凝视，画面仅截取头部至肩颈范围。人物佩戴一副玳瑁色圆框眼镜，镜片反射出微弱光点，深色短发覆盖额头。光线从上方投射，照亮面部上半部分，鼻梁与额头形成高光，下半张脸及背景完全隐没在深黑色阴影中。左侧可见浅色衣物边缘，整体色调偏暖褐，明暗对比强烈，营造出压抑、专注的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T16:33:01+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/shallowgrave047.jpg","observed_dimensions":[500,276],"source_thumbnail_dimensions":[500,276],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-8d863b13e2b0f349","origin":"visual"},{"work_id":"src-534eb63114e29d03","frame_id":"FG-f7c8a43d6c4424b0","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/shallowgrave060.jpg","source_page":"https://film-grab.com/2017/01/03/shallow-grave/","scene":"车内视角，右侧为黑色方向盘，左侧及前方堆叠着多捆印有“TRIPE”字样的报纸，报纸间夹杂一只浅色运动鞋，背景昏暗。","analysis":"画面采用车内主观视角，右侧前景占据约三分之一画面的是黑色方向盘，具有明显的橡胶纹理和金属中心盖。左侧及中部空间被多捆用胶带捆扎的报纸填满，报纸上印有巨大的黑色“TRIPE”字样，形成重复的视觉纹理。一只浅色运动鞋横放在报纸堆上。整体光线昏暗，色调偏冷，呈现出一种压抑、隐蔽的氛围。","prompt":"这是一张低分辨率的写实风格画面，视角位于车辆驾驶室内。画面右侧前景是一个巨大的黑色方向盘，占据了画面的右半部分，方向盘中心有金属标志，边缘有磨损痕迹。画面左侧和中部堆满了多捆用米色胶带捆扎的报纸，报纸封面印有巨大的黑色粗体英文单词“TRIPE”，报纸堆叠杂乱，填满了车厢空间。在报纸堆的上方，横放着一只灰白色的运动鞋，鞋带松散。背景处于阴影中，难以辨认具体细节，整体色调偏暗，以黑、白、灰为主，光线从上方投射，在报纸和方向盘上形成高光，营造出一种紧张、秘密的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T16:33:07+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/shallowgrave060.jpg","observed_dimensions":[500,276],"source_thumbnail_dimensions":[500,276],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-1e3933eb10d410db","origin":"visual"}]};